        "summary": "Airbnb在8月6日盘后发布二季度财报并上调全年收入增长预期，WSJ和财经媒体报道显示，公司季度收入约36.1亿美元，同比增长17%，净利润约8.16亿美元，Gross Booking Value约272亿美元。管理层称AI正在改善推荐、注册、登录、结账、房东工具和客服自动化，带动核心市场和扩张市场的夜间预订增长，股价盘后上涨约10%。",
